/**
 * 2026-08-22 HC:8 regression, worker-kernel-pending: while the warm-up tier serves an aggregate whose Janino compile is
 * below threshold, pending, or failed, the parallel rung must run interpreter-backed worker kernels — not demand a
 * compiled worker variant that cannot exist yet and decline every open with {@code worker-kernel-pending}. The fixture
 * pins codegen enabled with an unreachable compile threshold, so the sequential open is warm-up-interpreted
 * deterministically, and a {@code COUNT(DISTINCT)} aggregate forces the hook-distinct worker VARIANT (the shape whose
 * compile can never be available here).
 */
public class LmdbNativeAggregateParallelWarmupTest {

	private static final String EX = "http://example.com/";
	private static final String STRATEGY_DECLINES_METRIC = "nativeStrategyDeclines";

	private static final String[] PROPERTIES = {
			"rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.thresholdRows",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.kernelInterpreter.warmup",
			"rdf4j.lmdb.costCalibration.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.parallel.maxTasks",
			"rdf4j.lmdb.parallel.minWorkEstimate",
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.factorizedTail.enabled",
			"rdf4j.lmdb.adaptiveFilterPlacement.enabled" };

	private static final int CARS = 64;
	private static final int PRED2_FANOUT = 8;

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new HashMap<>();
	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		// Codegen ON with an unreachable threshold: every kernel request stays below threshold, so the warm-up
		// interpreter serves the sequential open — the exact state the parallel rung must survive.
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", String.valueOf(Long.MAX_VALUE / 8192));
		System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
		System.setProperty("rdf4j.lmdb.kernelInterpreter.warmup", "true");
		// Static ladder decides (irAggregate outranks its rivals once the short-circuits below are off), so the
		// parallel rung is reached deterministically instead of via learned dispatch.
		System.setProperty("rdf4j.lmdb.costCalibration.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "true");
		System.setProperty("rdf4j.lmdb.parallel.threads", "2");
		System.setProperty("rdf4j.lmdb.parallel.maxTasks", "4");
		System.setProperty("rdf4j.lmdb.parallel.minWorkEstimate", "0");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveFilterPlacement.enabled", "false");

		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI car = vf.createIRI(EX, "Car");
			IRI pred1 = vf.createIRI(EX, "pred1");
			IRI pred2 = vf.createIRI(EX, "pred2");
			// Single transaction, deliberately (per-add autocommit wedges direct adjacency into a revision gap).
			conn.begin();
			for (int i = 0; i < CARS; i++) {
				IRI subject = vf.createIRI(EX, "car" + i);
				conn.add(subject, RDF.TYPE, car);
				conn.add(subject, pred1, vf.createIRI(EX, "b" + (i % 20)));
				for (int j = 0; j < PRED2_FANOUT; j++) {
					conn.add(subject, pred2, vf.createIRI(EX, "c" + i + "_" + j));
				}
			}
			conn.commit();
		}
		try {
			assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		for (Map.Entry<String, String> property : previousProperties.entrySet()) {
			if (property.getValue() == null) {
				System.clearProperty(property.getKey());
			} else {
				System.setProperty(property.getKey(), property.getValue());
			}
		}
	}

	private static String countDistinctQuery() {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?b) AS ?count) WHERE { ?a a ex:Car . ?a ex:pred1 ?b . ?a ex:pred2 ?c }";
	}

	@Test
	public void warmupInterpretedAggregateStillEngagesTheParallelRung() {
		String query = countDistinctQuery();
		GenericPlanNode plan = explain(query);
		String declines = findMetric(plan, STRATEGY_DECLINES_METRIC);
		assertThat(declines == null ? "" : declines)
				.as("the warm-up-served aggregate must not demand a compiled worker variant")
				.doesNotContain("worker-kernel-pending");
		// The executed physical plan renders into the plan tree's string form; the parallel route stamp is the
		// user-visible proof that interpreter-backed workers ran.
		assertThat(plan.toString())
				.as("the parallel rung must engage with interpreter-backed workers while the compile is pending")
				.contains("irAggregateInterpretedParallel");
		assertThat(rows(query)).containsExactlyElementsOf(genericRows(query));
	}

	private GenericPlanNode explain(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return conn.prepareTupleQuery(query)
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(Object::toString)
					.sorted()
					.toList();
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty("rdf4j.lmdb.nativeQueryEngine.enabled");
		try {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty("rdf4j.lmdb.nativeQueryEngine.enabled");
			} else {
				System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", previous);
			}
		}
	}

	private static String findMetric(GenericPlanNode node, String metricName) {
		if (node == null) {
			return null;
		}
		String value = node.getStringMetricActual(metricName);
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findMetric(child, metricName);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}
}
